window.DECKS = window.DECKS || {};
window.DECKS.s2 = {
  polls: [
    { id: "s2-p20", q: "How does your team usually choose the sourcing route today?", options: ["Three quotes, whatever the category", "The business proposes, we follow", "We decide per category, but rarely write it down", "A documented strategy paper for every major project"] },
    { id: "s2-p21", q: "Nordvia P1 cleaning: what is the main risk in the re-tender?", options: ["Too few bidders", "Abnormally low bids below the wage floor", "Staff transfer costs nobody priced", "The timeline to June 2027"] },
    { id: "s2-p22", q: "What will be hardest when you present your strategy paper to the business owner?", options: ["Explaining why their favourite supplier must compete", "Getting a decision in time for the notice date", "Getting Risk and Compliance involved", "Defending the options we rejected"] }
  ],
  slides: [
    // ---------- Opening ----------
    { k: "title", h: "WHICH route to market?", sub: "Session 2 · Choosing the sourcing strategy" },
    { k: "statement", h: "The tool follows the strategy. The strategy follows the power position. Never the reverse.", p: "Today we choose how each category goes to market, and we write down why.", note: "Recall Session 1: we know what we buy and who holds the power. Today that analysis becomes a decision. Session 3 will design the tool." },
    { k: "steps", h: "Where we are in the course", s: [["WHAT are we sourcing?", "Done: need, category profile, power position"], ["WHICH route to market?", "Today: the sourcing strategy paper"], ["HOW do we run the event?", "Session 3: RFx, evaluation, e-auctions in Coupa"], ["HOW do we close it well?", "Session 4: negotiation, contract, handover"]], note: "Each session adds one part to the Sourcing Case. Today's part is the one the business owner must agree before any event is issued." },
    { h: "Today you will", b: ["Answer the six decisions of a sourcing strategy", "Choose a route with the strategy-selection matrix", "Design a single-supplier tender for cleaning or security", "Design a panel of preferred suppliers for professional and IT services", "Prepare a sole-source negotiation with an incumbent vendor", "Write the one-page strategy paper for your project"], note: "Read the six lines aloud. Ask each participant which of the three patterns their own project probably belongs to; we will test the guess at the end." },
    { k: "table", h: "Today's plan", t: [["Time", "Block"], ["0:00", "Opening and Fieldwork 1 debrief"], ["0:15", "2.1 The six decisions"], ["0:55", "2.2 One supplier by tender"], ["1:40", "2.3 A pool of preferred suppliers"], ["2:25", "2.4 Sole and single source"], ["3:05", "2.5 Partnerships, tail, strategy paper"], ["3:30", "Case 2 and close"]], note: "Two breaks: 1:30 and 2:55. Module 2.3 is the longest because it carries the most common indirect categories." },
    { k: "poll", poll: "s2-p1", note: "Use the result to pick two participants for the debrief: one whose scope changed and one who has not met the owner yet." },
    { k: "cards", h: "Fieldwork 1 debrief", c: [["Need", "Did the business owner confirm the need and the scope?"], ["Data", "Which contract or spend fact surprised you?"], ["Triage", "Did anything trigger outsourcing, DORA, data or staff transfer?"], ["Timing", "When is the notice date, not only the expiry?"]], note: "Trios for 8 minutes, then two examples in plenary. The notice date question is a deliberate bridge into today's timelines." },
    { k: "statement", h: "Nordvia runs about 60 sourcing events a year. Until now most were RFQs with three quotes, whatever the category.", p: "Same tool for cleaning, consulting and software licences. That is a habit, not a strategy.", note: "This is the case's starting point and probably familiar. Ask: what does three quotes achieve for a Kelvar renewal? For a consulting call-off?" },
    { k: "poll", poll: "s2-p20", note: "Do not judge the answers. Most teams decide per category but never write it down, and that is exactly what the strategy paper fixes." },

    // ---------- 2.1 ----------
    { k: "section", n: "2.1", h: "The six decisions of a sourcing strategy", sub: "How many suppliers, what relationship, what contract, what price model, what competition, how long?" },
    { k: "flow", h: "From analysis to tool", s: ["Category profile", "Power position", "Six decisions", "Route to market", "Tool and event"], p: "Sessions 1 → 2 → 3. Skipping a box is how three quotes became the default.", note: "Point at the last box: the RFP or auction is the output of the chain, not its start." },
    { k: "quote", q: "The Strategy stage chooses between competitive tendering and other approaches “based on supply position”.", by: "CIPS Procurement and Supply Cycle, stage 3", note: "CIPS and O'Brien (Innovation stage of the 5i model) agree: the choice of approach rests on the market and power analysis." },
    { k: "table", h: "Six decisions, in this order", t: [["#", "Decision", "Options"], ["1", "Number of suppliers", "Single, dual, multi (panel), sole"], ["2", "Relationship type", "Transactional, preferred, strategic partner"], ["3", "Contract architecture", "One-off, term contract, framework, catalogue, rate card"], ["4", "Commercial model", "Fixed, unit rates, T&M with rate card, capped T&M, output, gain-share"], ["5", "Competitive mechanism", "RFQ, RFP, multi-stage, mini-competition, auction, negotiation"], ["6", "Term", "Base term plus options"]], note: "The order matters: the mechanism is decision five. If you choose it first, the other four are made by accident." },
    { k: "table", h: "Decision 1: how many suppliers?", t: [["Option", "Strength", "Weakness", "Insurer fit"], ["Single", "Leverage, one accountable party", "Dependency in the term", "Cleaning, security, TMC"], ["Dual", "Continuity, benchmark tension", "Split volume, double cost", "Telecom, regional temp staff"], ["Multi / panel", "Specialists, competition per job", "Fragments if too large", "Consulting, IT services, agencies"], ["Sole", "None: a market fact", "Supplier power", "Proprietary core software"]], note: "Following Monczka et al. and Lysons and Farrington. Emphasise that sole source is not a choice we make; it is a fact we have to manage." },
    { k: "stats", h: "Fewer suppliers per unit of spend", s: [["3.7×", "fewer suppliers per $1bn of spend at Hackett's Digital World Class (2024)"], ["23%", "shorter sourcing cycle times at the same group"], ["≈ 2%", "of our Group's spend is under a Group contract today"], ["≈ 350", "IT services suppliers in the Group for about €80M"]], foot: "Hackett figures are consultancy benchmarks, not peer-reviewed results. Group figures anonymised and rounded.", note: "The point is direction, not a target number: concentration is associated with performance, and our Group is fragmented." },
    { k: "two", h: "Decisions 2 and 3: relationship and contract", l: { t: "Relationship type", b: ["Transactional: price and compliance", "Preferred supplier: priority, agreed terms", "Strategic partner: joint plans, open book"] }, r: { t: "Contract architecture", b: ["One-off contract for a defined project", "Term contract for a continuous service", "Framework with call-offs for a stream of needs", "Catalogue or rate card for repeat buys"] }, note: "Contract architecture follows the predictability of demand. A continuous service needs a term contract; unpredictable assignments need a framework." },
    { k: "table", h: "Decision 4: the commercial model", t: [["Model", "Use when"], ["Fixed price", "Scope and deliverables are clear"], ["Unit rates", "Volume varies, unit is clear (m², hours, devices)"], ["T&M with rate card", "Scope unclear, short discovery work"], ["Capped T&M", "Scope partly clear; protect the budget"], ["Output price", "Managed service with SLAs"], ["Gain-share", "Supplier controls the levers, baseline agreed"]], note: "The UK Consultancy Playbook gives the same logic for consulting. Who controls the outcome should carry the risk." },
    { k: "two", h: "Decision 5: two ways to compete", l: { t: "Competition FOR the market", b: ["One tender per cycle for the whole contract", "Then one supplier delivers and is measured", "Fits continuous site services"] }, r: { t: "Competition IN the market", b: ["Several pre-qualified suppliers stay in the game", "They compete again for every assignment", "Fits streams of specialist work"] }, note: "This distinction is the heart of the session. Cleaning: competition for the market. Consulting: competition in the market. Kelvar: neither, so negotiate." },
    { k: "cards", h: "Decision 6: the term", c: [["Supplier side", "Long enough to recover mobilisation and investment"], ["Our side", "Long enough to recover our switching cost"], ["Options", "Extensions earned by performance, not automatic"], ["Exit", "For ICT, aligned to a tested exit plan"]], note: "Ellram's TCO logic: mobilisation and transition are real post-transaction costs. Term length is a cost decision, not an admin one." },
    { k: "quad", h: "The Chessboard: four basic strategies", q: [["Change the nature of demand", "Supply power high, demand power low: re-specify, mine technical data"], ["Seek joint advantage", "Both high: value and cost partnership"], ["Manage spend", "Both low: demand management, bundling, catalogues"], ["Leverage competition", "Demand power high: tender, target pricing, auctions"]], hi: 3, axes: "Vertical: supply power · Horizontal: demand power (Kearney Purchasing Chessboard, Schuh et al.)", note: "Recall from Session 1. Each basic strategy points to a family of routes: tender and auction, partnership, channel, or negotiation plus demand change." },
    { k: "table", h: "The strategy-selection matrix", t: [["Situation", "Strategy", "Primary tool"], ["Recurring site service", "One supplier, 3 to 5-year cycle", "RFP, quality and price"], ["Stream of specialist jobs", "Panel with rate card", "Framework RFP, mini-competitions"], ["Proprietary incumbent", "Sole-source negotiation", "Usage audit, benchmark, BATNA"], ["Standard, price-driven", "Competitive single or dual", "RFQ, English reverse auction"], ["Complex transformation", "Partnership", "Multi-stage, dialogue, BAFO"], ["Tail", "Channel and automate", "Catalogue, punch-out, spot buy"]], note: "Research brief B.2, condensed. This is the reference table for the case at the end of the day." },
    { k: "steps", h: "Five route-to-market questions, in order", s: [["Real alternative?", "No → sole-source negotiation (2.4)"], ["How does demand arrive?", "Continuous → one supplier; assignments → panel; many small → catalogue"], ["Precise spec, automatic ranking?", "Yes, with 4–5 bidders → RFQ and auction possible"], ["Solution unknown?", "Yes → multi-stage negotiated process (2.5)"], ["Existing framework?", "Yes → call off before designing anything new"]], note: "Question 1 overrides everything. Question 5 is cheap and often forgotten: in our Group a framework may exist in another entity." },
    { k: "table", h: "Nordvia's pipeline through the questions", t: [["Project", "Demand shape", "Real alternative?", "Route"], ["P1 Cleaning", "Continuous", "Yes, many", "One supplier per lot by RFP"], ["P2 IT consulting", "Assignments", "Yes, many", "Panel with rate card"], ["P3 Kelvar", "Continuous", "Not for 18–24 months", "Sole-source negotiation"], ["P5 Supplies, print", "Many small orders", "Yes, many", "RFQ, auction, catalogue"], ["P8 Northbyte", "Complex service", "Yes, costly", "Multi-stage negotiated"]], foot: "Fictional case data.", note: "Do not reveal the full case answer yet; this slide shows the logic on five lines. Teams justify P1, P2, P3 and P5 in detail later." },
    { k: "example", h: "The six decisions for P1 cleaning", tag: "Example · Nordvia (fictional)", b: ["1 One supplier per country lot", "2 Preferred supplier, managed by KPIs", "3 Term contract per lot", "4 Fixed monthly fee plus unit rates, wage-index indexation", "5 RFP with quality and price, negotiation round", "6 3 years + 1 + 1"], note: "This is a worked example of the practice. Ask: which of these six would change if HQ were the only site?" },
    { k: "exercise", h: "The six decisions for your project", min: 15, where: "Module 2.1 in your workbook", b: ["Bring forward your Kraljic and Chessboard position", "Say how demand arrives", "Answer the six decisions, one line each", "For each one, write the option you rejected and why", "Swap with a neighbour: challenge one decision"], note: "Walk the room and read the \"rejected\" column. That is where you see whether a participant made a decision or followed a habit." },
    { k: "debrief", h: "Debrief", b: ["Which decision was hardest to answer?", "Where did your Session 1 position change your mind?", "Who chose the mechanism before the number of suppliers?", "Which option did you reject that the business would have chosen?"], note: "The last question prepares Fieldwork 2: the rejected options are what the business owner will ask about." },
    { k: "takeaways", h: "2.1 in three lines", b: ["Six decisions, in order: the mechanism is the fifth", "Compete for the market, in the market, or negotiate", "Write down the rejected options: they are your argument"], note: "Link forward: the next three modules take the three patterns one by one." },

    // ---------- 2.2 ----------
    { k: "section", n: "2.2", h: "One supplier, chosen by tender", sub: "Cleaning, security, reception and soft FM" },
    { k: "statement", h: "For cleaning and security, competition happens once every three years or so, for the whole contract. Make that moment count.", note: "Everything in this module is about designing the one competitive moment well, and then holding one supplier to account." },
    { k: "cards", h: "Why one supplier per site or cluster", c: [["Accountability", "One provider answers for the result in a building"], ["Leverage", "Bundled hours: better routes, supervision and price"], ["Mobilisation", "Each change costs recruitment, training, a service dip"], ["Governance", "One set of KPIs, one review, one invoice"]], note: "Two cleaners on one floor means two excuses. Splitting a site does not add competitive tension during the term; it only adds interfaces." },
    { k: "table", h: "The playbook for site services", t: [["", "Cleaning", "Security and reception"], ["Position", "Leverage", "Leverage to bottleneck"], ["Suppliers", "One per region or cluster", "One, possibly with reception"], ["Tool", "RFP, site visits, staff data", "RFP, presentations, references"], ["Price model", "Fixed fee + unit rates", "Hourly rates by role + fee"], ["Term", "3 + 1 + 1", "3 + 1 + 1 or 3 + 2"]], foot: "Terms are common practice, not norms (research brief G.2).", note: "Security moves towards bottleneck because of licensing and vetting: fewer providers qualify, so quality weighting goes up." },
    { k: "stats", h: "What public tenders show", s: [["3 + 2 × 12 months", "UK university cleaning contract, 2024, 50/50 quality and price"], ["5 + 3 + 1 + 1", "HMRC integrated FM call-off, 2024"], ["≤ 4 years", "EU public benchmark for frameworks (Dir. 2014/24 Art. 33)"]], foot: "Public examples cited in the research brief; useful reference points for private buyers.", note: "The larger and more integrated the scope, the longer the term. Office cleaning sits at the short end." },
    { k: "cards", h: "Why 3 + 1 + 1", c: [["3-year base", "Recovers mobilisation, equipment, training, CAFM set-up"], ["+1", "Earned by performance against KPIs"], ["+1", "Earned again; keeps tension until the end"], ["Then", "Re-tender: competition for the market again"]], note: "Options are leverage only if extension depends on performance. Write that condition into the contract, and put the dates in CLM." },
    { k: "table", h: "Input, output or hybrid?", t: [["Type", "Describes", "Strength", "Risk"], ["Input", "Hours, frequencies, headcount", "Easy to audit", "Pay for hours, not results"], ["Output", "Cleanliness standards, response times", "Supplier proposes method", "Hard to draft and assess"], ["Hybrid", "Outputs, plus methods where we need control", "Usual best fit", "Needs clear boundaries"]], foot: "CMS (Hanson, 2000); Singapore NEA outcome-based cleaning guide.", note: "Security: prescribe procedures, vetting and licences; specify outputs elsewhere. That is a hybrid by design." },
    { k: "example", h: "A hybrid specification for Nordvia HQ", tag: "Example · Nordvia (fictional)", b: ["Offices and meeting rooms: output standard, audited monthly", "Washrooms: output standard plus a minimum check frequency", "Server rooms and archives: prescribed method, vetted staff only", "Complaints: response time as a KPI", "Supplier proposes the method and hours, priced per site"], note: "The HQ complaints in the case make this concrete: an output standard lets us measure what the complaints are about." },
    { k: "two", h: "Quality and price weighting", l: { t: "Weights", b: ["Quality at least 50% for site services", "Fixed and published before issue", "Price scored on total annual cost"] }, r: { t: "Quality criteria", b: ["Method and staffing plan", "Mobilisation and staff transfer plan", "KPIs and reporting", "Fair labour and ESG"] }, note: "Session 3 builds the full evaluation model and tests sensitivity. Today we only set the principle in the strategy." },
    { k: "steps", h: "The should-cost floor", s: [["Hours", "Hours needed per site, from the specification"], ["Wage", "× collectively agreed wage"], ["On-costs", "+ statutory costs, holidays, sickness"], ["Supervision and materials", "+ supervision, consumables, equipment"], ["Overhead and margin", "+ a reasonable overhead and margin"]], note: "Labour is most of the cost in cleaning and security. A bid below this floor cannot be paid without breaking a rule somewhere." },
    { k: "statement", h: "A bid below the wage floor is not a saving. It is a future service failure, or a legal exposure, with our name on it.", p: "Ask for an explanation of every abnormally low bid, and document it.", note: "CCS guidance asks buyers to seek explanations for abnormally low bids. No study quantifies auction-driven failures in cleaning, so present it as risk logic." },
    { k: "cards", h: "Staff transfer changes the economics", c: [["The rule", "Acquired Rights Directive 2001/23/EC; national rules differ"], ["Case law", "Süzen (C-13/95): transfer if a major part of the workforce moves"], ["National", "TUPE in the UK; collective agreements mandate takeover in some countries"], ["In the RFP", "Staff data, realistic savings, mobilisation time"]], note: "Check national law with Legal. When staff transfer, the savings come from method and management, not from wages." },
    { k: "table", h: "Price, indexation and KPIs", t: [["Element", "Design"], ["Base price", "Fixed monthly fee per site"], ["Variations", "Unit rates for extras and events"], ["Indexation", "Once a year, wage-index formula"], ["KPIs", "Audit score, response time, complaints"], ["Service credits", "Linked to KPIs, capped"]], note: "Nordvia P6 security had hourly rates indexed twice in two years and no KPIs: both are strategy failures, not contract details." },
    { k: "two", h: "An e-auction for cleaning?", l: { t: "Never", b: ["Price-only auction on the open market", "Before quality is evaluated", "Without a should-cost floor"] }, r: { t: "Possible, with care", b: ["Only among bidders above a quality threshold", "Only above the should-cost floor", "Rules disclosed in advance"] }, hi: "r", note: "The research brief rates e-negotiation fit for these services as medium. Most teams will prefer a negotiation round or BAFO." },
    { k: "example", h: "P6 security and reception", tag: "Example · Nordvia (fictional)", b: ["€1.6M a year, one provider, expiry December 2027", "Hourly rates indexed twice in two years; no KPIs", "Route: one supplier by RFP, 3 + 1 + 1, hybrid specification", "Strong weight on vetting, licences, training, response times", "Indexation by formula; KPIs with service credits"], note: "Same pattern as cleaning, different weights. Ask: could P1 and P6 be one soft-FM tender? Answer: possibly per country, if the market offers both." },
    { k: "cards", h: "In Coupa", c: [["Event", "RFP with one lot per country; items in a lot awarded together"], ["Content", "Questionnaires, pricing template with hours, draft contract attached"], ["Q&A", "Message Center for site-visit questions"], ["Contract", "CLM with option dates and notice alerts"]], foot: "Weighted scoring set-up and sealed opening: confirm in your tenant.", note: "The lot rule matters: if Nordvia wants to allow one bidder to win one country only, the countries must be separate lots." },
    { k: "poll", poll: "s2-p21", note: "All four are real risks. Most groups pick the low bids; push them on the timeline, which is the risk they control least." },
    { k: "exercise", h: "The Nordvia cleaning re-tender", min: 15, where: "Module 2.2 in your workbook", b: ["Choose the lot structure and the term", "Choose the specification type", "Set quality and price weights", "Tick the safeguards you would build in", "Plan back from June 2027: issue, award, mobilisation"], note: "Breakout rooms of three. Remind them a standard tender needs 9 to 12 months before expiry, plus mobilisation." },
    { k: "debrief", h: "Debrief", b: ["One lot or one per country, and why?", "Who chose output, who hybrid?", "What weight did you give quality?", "Is there still time before June 2027? What is plan B?"], note: "Expected answer: one lot per country with a bundle option, 3 + 1 + 1, hybrid, quality at least 50%. Plan B: a short bridge extension, decided, not rolled over." },
    { k: "takeaways", h: "2.2 in three lines", b: ["One supplier per site or cluster, chosen by tender, 3 + 1 + 1", "Hybrid specification, quality at least 50%, should-cost floor", "Staff transfer, indexation and KPIs belong in the strategy"], note: "Bridge to 2.3: now the opposite case, where several suppliers are the right answer." },

    // ---------- 2.3 ----------
    { k: "section", n: "2.3", h: "A pool of preferred suppliers", sub: "Professional services, consulting and IT services" },
    { k: "statement", h: "Professional and IT services arrive as a stream of different assignments. No single firm is best at all of them, and no RFP per assignment is fast enough.", p: "The answer is a panel: terms fixed once, competition every time.", note: "Contrast with cleaning: one continuous service there, many different jobs here. That single difference changes the whole strategy." },
    { k: "stats", h: "Nordvia IT consulting today", s: [["€6.1M", "with 12 firms through 38 call-offs"], ["61%", "of the spend with the top 3 firms"], ["29 of 38", "call-offs awarded without competition"], ["820–1,450", "euros a day for the same senior profile"]], foot: "Fictional case data.", note: "Let the numbers land. Fragmented and concentrated at once: many firms, but most work goes to three favourites without competition." },
    { k: "poll", poll: "s2-p2", note: "Most pick the panel. Ask the few who chose an auction: what would you be ranking, and is a senior architect from two firms the same product?" },
    { k: "stats", h: "The Group picture", s: [["≈ €80M", "IT services, some 350 suppliers"], ["≈ €49M", "consulting and audit, some 360 suppliers"], ["≈ €12M", "advisory firms in 9 entities, 60 supplier records, no Group agreement"], ["≈ 5%", "of IT services spend with a supplier shared by two entities"]], foot: "Anonymised and rounded.", note: "The same pattern as Nordvia, at Group scale. A panel can be local first and Group later; design it so other entities can join." },
    { k: "table", h: "Three wrong answers and one right one", t: [["Approach", "What happens"], ["One supplier for everything", "Dependency, capability gaps, no tension"], ["Open market every time", "Weeks per RFP; people skip it and pick a favourite"], ["No rules (today)", "Same profile at very different rates"], ["Panel by lot, rate card", "Ceilings fixed once; 3–6 firms compete per job"]], note: "The third row is where most organisations are. The panel is not more bureaucracy; it is less work per assignment." },
    { k: "table", h: "The reference model: EU Art. 33", t: [["Call-off route", "When", "How"], ["Direct award", "All terms fixed", "Objective criteria: cascade, rotation, capability"], ["Mini-competition", "Not all terms fixed", "Invite all capable members in writing; deadline; bids closed until it"], ["Mix", "Defined in the framework", "Rules stated upfront"]], foot: "Directive 2014/24/EU Art. 33, maximum 4 years. A public-sector rule; a benchmark for private buyers.", note: "The private insurer is not bound by the Directive, but the logic is sound and auditors recognise it." },
    { k: "example", h: "Practice from the UK: CCS consultancy framework", tag: "Public example · CCS RM6187", b: ["9 lots, one lot per further competition", "Maximum day rates that call-offs may not exceed", "At least 10 working days for simple requirements", "Quality 50–90%, price 10–50%", "Three evaluators and a consensus meeting", "No negotiation after bids, clarification only"], note: "This is the most detailed public model of a consulting panel. Take the structure; adapt the thresholds to your delegation of authority." },
    { k: "steps", h: "Designing the panel in six steps", s: [["Lots", "By capability, maybe by size band"], ["Panel size", "Enough to compete, few enough to engage"], ["Rate card", "Max day rates, discounts, expenses, indexation cap"], ["Call-off rules", "Thresholds for direct award and mini-competition"], ["Call-off template", "SOW, deliverables, acceptance, key people"], ["Governance", "Scorecards, share of wallet, refresh, exit"]], note: "Each step answers a typical failure: no lots means generalists win everything; no rules means favourites win everything." },
    { k: "table", h: "Lots for an insurer's IT and professional services", t: [["Lot", "Scope", "Typical pricing"], ["IT delivery", "Projects and programmes", "Fixed price per milestone"], ["Technology advisory", "Architecture, cloud, security", "Fixed price per deliverable"], ["IT staff augmentation", "Developers, testers, analysts", "T&M at rate card"], ["Regulatory and actuarial", "Solvency II, IFRS 17, DORA", "Fixed price or capped T&M"], ["Strategy and transformation", "Operating model, programmes", "Fixed price per phase"]], foot: "Illustrative lot structure; adapt to your demand.", note: "Ask participants which lots their own demand would need. Usually two or three lots cover most of an entity's spend." },
    { k: "cards", h: "How many firms per lot?", c: [["Too few (1–2)", "No real competition per assignment"], ["Practice range", "Three to six per lot"], ["Too many (10+)", "Members get little work and stop investing"], ["Test", "Can each member expect meaningful work in a year?"]], foot: "Three to six is common practice, not a verified norm.", note: "A panel member that never wins anything stops putting its best people forward. Size the panel to the demand." },
    { k: "example", h: "Panel consolidation in insurance", tag: "Analogue · claims legal panels", b: ["Zurich: England and Wales panel cut from 28 to 14 firms (2004)", "Five separate panels replaced by one central system", "Co-operative Insurance Society: from 27 firms to possibly six (2005)", "Reasons cited: unequal work distribution, quality"], foot: "The Lawyer, 2003 and 2005. Claims legal, not indirect: present as an analogue.", note: "These are the best-documented insurance panel cases. The logic transfers: fewer firms, more work each, more leverage and quality." },
    { k: "table", h: "Rate card structure", t: [["Element", "Design"], ["Roles", "Role families per lot"], ["Seniority", "Junior, Consultant, Senior, Manager, Principal"], ["Price", "Maximum day rate; call-offs may bid lower"], ["Volume", "Discount tiers on annual spend"], ["Expenses", "Policy fixed, or included in the rate"], ["Indexation", "Annual cap"]], note: "Maximum, not fixed rates: the mini-competition can still bring the price down. The ceiling stops the 1,450-euro day." },
    { k: "table", h: "Call-off rules", t: [["Value or situation", "Rule"], ["Below €50K", "Direct award at or below rate card, written rationale"], ["€50K to €250K", "Mini-competition, at least 3 members invited"], ["Above €250K or strategic", "Mini-competition with presentations, or full RFP"], ["Urgent", "Direct award, reviewed after the fact"], ["Follow-on work", "Direct award if justified, benchmarked"]], foot: "Thresholds are illustrative: align them to your delegation of authority.", note: "The €50K line echoes the Group's size bands. The rule that matters most: every direct award has a written rationale." },
    { k: "two", h: "Fixed price or T&M?", l: { t: "Fixed price per deliverable", b: ["Default for defined work", "Supplier carries delivery risk", "Needs a clear SOW and acceptance"] }, r: { t: "Capped or pure T&M", b: ["Capped T&M when scope is partly clear", "Pure T&M only for discovery", "Payment by results only if the supplier controls the levers"] }, foot: "UK Consultancy Playbook (2022): three pricing models.", note: "Most of Nordvia's 38 call-offs were probably T&M. Moving defined work to fixed price is a saving and a control." },
    { k: "two", h: "Labour law in staff augmentation", l: { t: "Service contract", b: ["Supplier owns the outcome", "Supplier directs its people", "Fixed price deliverables fit"] }, r: { t: "Temporary agency work", b: ["We direct the people", "Must be labelled and licensed", "Limits apply, e.g. 18 months in Germany (AÜG)"] }, foot: "Sham service contracts can create an employment relationship with the client. Verify current national law with Legal.", note: "This is a strategy decision, not a contract detail. Choose the model per lot and design the SOW accordingly." },
    { k: "cards", h: "DORA and the IT panel", c: [["Scope", "IT services with system access: likely ICT services"], ["Register", "Every ICT arrangement goes in the register of information"], ["Clauses", "Art. 30 clauses in the framework, inherited by every call-off"], ["Assessment", "Art. 28(4) pre-contract assessment at panel level"]], note: "Doing DORA once at framework level instead of 38 times is a strong argument for the panel with the CIO." },
    { k: "example", h: "A panel for Nordvia P2", tag: "Example · Nordvia (fictional)", b: ["Lot 1 IT delivery · Lot 2 technology advisory · Lot 3 staff augmentation", "Four firms per lot, chosen by a framework RFP", "Maximum day rates by role and seniority", "Mini-competition from €50K, direct award below with rationale", "DORA clauses and labour-law model fixed per lot", "Framework 3 years + 1"], note: "One possible design, not the answer. The incumbent favourites can join, but they must win a place on the panel." },
    { k: "example", h: "P7 creative agencies: a roster", tag: "Example · Nordvia (fictional)", b: ["€7.2M with 6 agencies, overlapping briefs, no rate card", "Lead creative agency chosen by pitch", "Small specialist panel for production and digital", "Rate card for fees; production at cost plus transparent mark-up", "No auctions for creative work"], note: "Same logic as consulting, with a twist: a lead agency relationship is closer to strategic. EU Art. 35 bans auctions for intellectual work." },
    { k: "cards", h: "In Coupa", c: [["Framework", "Contract and rate card in CLM"], ["Mini-competition", "Short RFP event from a template, only to the lot's members"], ["Q&A", "Message Center for equal treatment and audit trail"], ["Buying", "Requisitions reference the framework; off-panel spend shows"]], note: "The template is the time saver: a mini-competition should be issued in an hour, not a week." },
    { k: "exercise", h: "Design the Nordvia IT services panel", min: 20, where: "Module 2.3 in your workbook", b: ["Check the two numbers from the case", "Define the lots and the number of firms per lot", "Sketch the rate card by role and seniority", "Write the call-off rules", "Add the labour-law and DORA safeguards"], note: "Answers to the checks: 76% of call-offs without competition; the top rate is 77% above the lowest." },
    { k: "debrief", h: "Debrief", b: ["How many lots, and why those?", "How many firms per lot?", "Where did you set the direct-award threshold?", "What will the CIO say to the rules, and how will you answer?"], note: "Push on the last question. The favourite firm can stay if it competes; speed comes from the template, not from skipping competition." },
    { k: "takeaways", h: "2.3 in three lines", b: ["Streams of assignments → a panel by lot with a rate card", "Mini-competition above a threshold, documented direct award below", "Labour-law model and DORA clauses fixed once, in the framework"], note: "Bridge to 2.4: now the case where no competition is possible at all." },

    // ---------- 2.4 ----------
    { k: "section", n: "2.4", h: "When there is no real competition", sub: "Sole and single source: incumbent software and proprietary platforms" },
    { k: "statement", h: "An RFP sent to a vendor who knows it cannot lose is theatre. An auction with one realistic bidder is an expensive RFQ.", p: "Negotiate, and change the game before you sit down.", note: "GAO found over a third of US federal reverse auctions in FY2012 had no interactive bidding. A tool without competition gives nothing." },
    { k: "two", h: "Sole or single source?", l: { t: "Sole source", b: ["No alternative exists", "Proprietary intellectual property", "Strategy: protect and reduce dependency"] }, r: { t: "Single source", b: ["Alternatives exist", "Switching is slow or costly", "Strategy: make the alternative credible"] }, hi: "r", note: "Most incumbent software is single source with high switching cost. That is a weaker vendor position than it first looks." },
    { k: "quad", h: "How does the vendor see us?", q: [["Development", "Low value to them, attractive: they want to grow us"], ["Core", "High value and attractive: they will invest in us"], ["Nuisance", "Low value, unattractive: little effort for us"], ["Exploitable", "High value, unattractive: they will take margin"]], hi: 3, axes: "Vertical: attractiveness of our account · Horizontal: relative value to the supplier (Steele and Court, 1996)", note: "A mid-sized insurer is often nuisance or exploitable to a global software vendor. Strategic for us and exploitable for them is the danger zone." },
    { k: "cards", h: "Getting out of the danger zone", c: [["Raise attractiveness", "Aggregate Group volume, reference value, easy payment"], ["Reduce dependency", "Credible alternative for the next term"], ["Re-specify", "Fewer modules, different architecture"], ["Mine the data", "Usage, entitlement, deployment"]], note: "These are the Chessboard's \"change the nature of demand\" moves, plus the preferencing logic. Paying late makes us less attractive; paying on time alone does not make us a customer of choice." },
    { k: "steps", h: "The sole-source playbook", s: [["Start early", "12–18 months before renewal (practice rule)"], ["Know usage", "Entitlement vs deployment, users, modules"], ["Build the BATNA", "RFI to alternatives, architecture study, scope cut"], ["Benchmark", "Price per user or module, discounts, uplift caps"], ["Unbundle", "Licences, support, cloud, services"], ["Protect", "Uplift caps, right to reduce, exit, data return"], ["One voice", "IT, Finance and Procurement aligned"]], note: "Research brief C.8. The notice date, not the expiry date, is the deadline for step one." },
    { k: "example", h: "P3 Kelvar: the facts", tag: "Case · Nordvia (fictional)", b: ["€11.2M a year; 9% uplift at the last renewal", "Renewal June 2027; 9-month notice period; auto-renewal clause", "An estimated 20 to 25% of named-user licences unused", "Two credible alternative platforms; migration 18 to 24 months", "No usage data was collected until now"], note: "Ask the room to compute the real deadline: nine months before June 2027. Then ask what the auto-renewal clause does if nobody acts." },
    { k: "two", h: "BATNA: bluff or credible?", l: { t: "Bluff", b: ["\"We will move to another platform\"", "No study, no budget, no timeline", "The vendor knows the migration takes two years"] }, r: { t: "Credible", b: ["RFI answered by both alternatives", "Architecture study and migration plan", "A decision point for the next term"] }, hi: "r", foot: "Fisher and Ury: your power depends on the attractiveness of your alternative. Improve it before negotiating.", note: "A bluff that is called destroys the position for years. A credible BATNA does not need to be used to work." },
    { k: "example", h: "What shelfware is worth", tag: "Illustrative calculation · Nordvia (fictional)", b: ["Assume half of the €11.2M is named-user licences", "20 to 25% of them unused", "Value: about €1.1M to €1.4M a year", "Plus the 9% uplift that was applied to unused licences too"], foot: "The 50% licence share is an assumption for training, not a case fact.", note: "Usage data is the cheapest lever: it costs nothing to the vendor relationship and it is objective. Fisher and Ury's objective criteria." },
    { k: "cards", h: "Unbundle and re-bundle", c: [["Licences", "Right-size to deployment; right to reduce"], ["Support", "Cap the uplift; consider levels"], ["Cloud subscription", "Price per user, term, data location"], ["Services", "Separate; compete them on the panel"]], note: "Services around the software can often be competed even when the licence cannot. That reopens competition on part of the spend." },
    { k: "table", h: "Protect the next term", t: [["Protection", "Why"], ["Cap on renewal uplifts", "No more 9% surprises"], ["Price hold", "Budget certainty for the term"], ["Right to reduce volumes", "Pay for what is deployed"], ["Transition assistance", "Makes the BATNA real next time"], ["Data portability and return", "Exit without hostage-taking"], ["DORA exit and transition clauses", "Mandatory if a critical or important function"]], note: "DORA Art. 30(3)(f) applies where the software supports a critical or important function, which a core insurance platform usually does." },
    { k: "flow", h: "Plan back from the notice date", s: ["T−18 m: usage audit", "T−15 m: RFI to alternatives", "T−12 m: benchmark, mandate", "T−9 m: notice decision", "T−6 m to T: negotiation, sign"], p: "T = renewal date. With a 9-month notice period, the notice decision falls at T−9. Practice timeline, not a norm.", note: "For Kelvar, compute T−9 against June 2027 and check whether a protective notice is still possible. If it is not, the auto-renewal clause shapes the next term." },
    { k: "two", h: "Do and never do", l: { t: "Never", b: ["An auction with one realistic bidder", "An RFP for show", "IT pre-committing before the mandate", "Long terms without exit rights"] }, r: { t: "Do", b: ["Facts first: usage and benchmarks", "A credible BATNA for the next term", "One voice, one mandate", "Protections over headline discount"] }, hi: "r", note: "The most common failure is the third one on the left: a stakeholder tells the vendor the renewal is a formality." },
    { k: "cards", h: "In Coupa", c: [["No auction", "No RFP for show either"], ["RFI event", "To alternative vendors, to build the BATNA"], ["CLM", "Alerts on the notice date, not only expiry"], ["Workflow", "Record the justification and the outcome"]], note: "Coupa's role here is data and documentation, not competition. That is the honest use of the tool in a sole-source case." },
    { k: "poll", poll: "s2-p3", note: "The right answer is the second. The alternatives cannot replace Kelvar by June 2027, but they shape the next term and the protections." },
    { k: "exercise", h: "Sole-source renewal outline", min: 12, where: "Module 2.4 in your workbook", b: ["Check the illustrative shelfware value", "Fill the eight boxes of the outline", "Tick \"assumed\" where a fact is still missing", "Use Kelvar or your own sole-source project"], note: "Correct check answer: €1.12M (illustrative). The canvas mirrors the playbook; Session 4 turns it into a full negotiation plan." },
    { k: "debrief", h: "Debrief", b: ["What is your BATNA, honestly?", "Which protection matters most for the next term?", "Who speaks for Nordvia, and who must stay silent?", "What would you unbundle and compete?"], note: "If a team writes \"leave Kelvar by June 2027\" as BATNA, ask them to prove it. That is the bluff of the previous slide." },
    { k: "takeaways", h: "2.4 in three lines", b: ["No real competition → negotiation, not an RFP for show or an auction", "Usage facts, benchmarks and a credible BATNA create the power", "Protect the next term and change the nature of demand"], note: "Bridge to 2.5: the two ends of the map, and the paper that records the decision." },

    // ---------- 2.5 ----------
    { k: "section", n: "2.5", h: "Strategic partnerships and the tail", sub: "Two ends of the map, and the paper that records your decision" },
    { k: "steps", h: "A multi-stage process for complex deals", s: [["RFI", "Pre-qualify capability and compliance"], ["RFP stage 1", "Solution and indicative price"], ["Shortlist", "Three or four bidders"], ["Dialogue", "Workshops on solution, risk, exit"], ["BAFO", "Final offers against fixed criteria"], ["Award", "Then contract and transition"]], foot: "Borrowed from the EU competitive procedure with negotiation and competitive dialogue (Arts. 29–30), without their legal constraints.", note: "Coupa supports this with follow-on events where responses carry over. Chessboard: seek joint advantage." },
    { k: "table", h: "Regulation in the strategy", t: [["Question", "Effect on the strategy"], ["Critical or important outsourcing? (Solvency II Art. 49)", "Prior notification: lead time in the plan"], ["Provider selection (Del. Reg. 2015/35 Art. 274)", "Detailed examination of ability and capacity"], ["ICT for a critical function? (DORA Art. 28)", "Pre-contract assessment, concentration risk, tested exit"], ["Any ICT service?", "Register of information; Art. 30(2) clauses"]], foot: "EIOPA cloud guidelines withdrawn from 17 January 2025. Legal and Compliance own the interpretation.", note: "These questions come from the Session 1 triage. Here they change the timeline and the criteria, so they belong in the strategy paper." },
    { k: "example", h: "P8 Northbyte: the partnership case", tag: "Example · Nordvia (fictional)", b: ["Claims IT managed service, €19.4M a year, expiry December 2027", "Supports a critical function; in the DORA register", "No tested exit plan", "Route: multi-stage negotiated process, starting now", "Exit feasibility as a selection criterion, not a contract annex"], note: "Even if Northbyte stays, the process builds the exit plan DORA requires. Without alternatives, there is no tested exit." },
    { k: "stats", h: "The tail in numbers", s: [["80–90%", "of purchased items are tail spend (McKinsey, 2018)"], ["10–20%", "of spend is in the tail"], ["5–15%", "estimated savings potential in the tail"], ["86% · 12%", "Group: share of supplier records below €50K, and their share of spend"]], foot: "McKinsey addresses mainly direct industrial spend. Many other tail statistics in circulation are vendor-sourced.", note: "The tail is an efficiency topic first. The savings are real but secondary to the process cost." },
    { k: "example", h: "P5 office supplies and print", tag: "Example · Nordvia (fictional)", b: ["€2.3M with 31 suppliers; 1,900 POs a year below 1,000 euros", "First: is there a Group framework?", "If not: RFQ on a basket of top items", "English reverse auction if 4–5 qualified bidders compete", "Then a punch-out catalogue; print as a separate lot"], note: "This is the one project of the day where an auction fits: precise basket, many bidders, price decides, low switching cost." },
    { k: "cards", h: "E-auction: the preconditions", c: [["Specification", "Precise; bids can be ranked automatically"], ["Bidders", "At least four to five qualified"], ["Decision", "Price, or a formula, decides"], ["Relationship", "Can bear it; credible award intent"]], foot: "Smeltzer and Carr 2003; Jap 2002, 2007; EU Dir. 2014/24 Art. 35. Session 3 goes deeper.", note: "A preview of Session 3. Today the point is only where an auction fits on the map, and where it never fits." },
    { k: "table", h: "The one-page strategy paper", t: [["Block", "Content"], ["1 Need and scope", "Validated need, value, expiry, notice date"], ["2 Position", "Kraljic, Chessboard, how the incumbent sees us"], ["3 Route to market", "The six decisions, one line each"], ["4 Options rejected", "What we will not do, and why"], ["5 Timeline", "Back from the notice date"], ["6 Risks and regulation", "Outsourcing, DORA, data, labour law"], ["7 Decision requested", "From whom, by when"]], note: "One page is a discipline. If the route needs two pages to justify, the analysis is not finished." },
    { k: "example", h: "Strategy paper: P2 in seven lines", tag: "Example · Nordvia (fictional)", b: ["Need: IT consulting €6.1M, 12 firms, no framework", "Position: leverage; competition among suppliers", "Route: panel, 3 lots, 4 firms each, rate card, call-off rules", "Rejected: single supplier (dependency); open RFP per job (speed)", "Timeline: framework RFP Q1, panel live by Q3", "Risks: AÜG model per lot, DORA clauses in the framework; decision: CIO"], foot: "Quarters illustrative.", note: "Show how short it can be. The rejected options line is the one the CIO will read twice." },
    { k: "poll", poll: "s2-p4", note: "Collect the distribution: a mix of all patterns shows the logic is being applied rather than one habit replaced by another." },
    { k: "exercise", h: "Your one-page strategy paper", min: 12, where: "Module 2.5 in your workbook", b: ["Choose your route to market", "Fill the seven blocks, short lines", "Write the options you rejected", "Plan back from the notice date", "Name who must decide"], note: "It will not be finished now. The aim is a draft good enough to take to the business owner in Fieldwork 2." },
    { k: "debrief", h: "Debrief", b: ["Which route did you choose, and which did you reject?", "Is your timeline realistic from the notice date?", "Who outside Procurement must sign off?"], note: "Collect the routes chosen on a board: a mix of all three patterns is a good sign the logic was applied." },
    { k: "takeaways", h: "2.5 in three lines", b: ["Complex deals: multi-stage process with dialogue and BAFO", "Tail: channel through catalogues, punch-out and spot buy", "One page records the route, the rejected options and the decision"], note: "Bridge to the case: four projects, four routes, one logic." },

    // ---------- Case 2 ----------
    { k: "section", n: "Case 2", h: "Four projects, four routes to market", sub: "Nordvia Insurance, a fictional mid-sized insurer" },
    { k: "example", h: "The situation", tag: "Case 2 · Nordvia (fictional)", b: ["Procurement team of 9, about 60 events a year in Coupa", "Until now: mostly RFQs with three quotes", "The Head of Procurement wants a route for four projects", "Each justified with the strategy-selection matrix"], note: "Teams of three or four. They present one project each in the debrief." },
    { k: "table", h: "The four projects", t: [["Project", "€M", "Suppliers", "Expiry", "Today"], ["P1 Office cleaning", "2.4", "3 local", "Jun 2027", "Rolled over since 2019; HQ complaints"], ["P2 IT consulting", "6.1", "12 firms, 38 call-offs", "No framework", "820–1,450 euros a day"], ["P3 Kelvar licences", "11.2", "1 vendor", "Jun 2027", "9% uplift; auto-renewal"], ["P5 Supplies and print", "2.3", "31", "Various", "1,900 POs below 1,000 euros"]], foot: "Fictional case data.", note: "Remind them of the extra facts: Kelvar 9-month notice, 20–25% unused licences, migration 18–24 months; 29 of 38 consulting call-offs without competition." },
    { k: "exercise", h: "Your team's answer", min: 15, where: "Case tab in your workbook", b: ["Choose the route for each project", "Number of suppliers, mechanism, term", "Justify with position and facts", "Name the first step", "Add one thing you would never do"], note: "Give 15 minutes of team work and 10 for the debrief. Ask each team to defend one project they found hard." },
    { k: "table", h: "One possible answer", t: [["Project", "Route", "Term", "Never"], ["P1 Cleaning", "One supplier per country lot, RFP", "3 + 1 + 1", "Price-only auction"], ["P2 Consulting", "Panel, 3 lots, rate card", "3 + 1", "Auction on day rates"], ["P3 Kelvar", "Sole-source negotiation, BATNA", "Aligned to roadmap", "RFP for show"], ["P5 Supplies", "Group check, RFQ, auction, catalogue", "2–3 years", "Tender every small order"]], note: "Other answers are defensible if the logic holds, for example one lot for all cleaning sites. What is not defensible is the same tool for all four." },
    { k: "two", h: "What separated the strong answers", l: { t: "Weaker", b: ["Started from the tool", "Same mechanism for all four", "No timeline from the notice date"] }, r: { t: "Stronger", b: ["Started from demand shape and alternatives", "Named rejected options", "Planned back from notice dates", "Saw the Group framework question"] }, hi: "r", note: "Read the right column as the checklist for Fieldwork 2." },
    { k: "debrief", h: "Debrief", b: ["Which project did your team argue about most?", "Did anyone choose an auction for P2 or P3? Why not?", "What is the first step for Kelvar this month?", "Which project is most at risk on timing?"], note: "P1 and P3 both expire June 2027; P3's notice period makes it the most urgent. That is the timing insight to land." },

    // ---------- Close ----------
    { k: "table", h: "Three patterns, one logic", t: [["Demand and market", "Route", "Example"], ["One continuous site service, many suppliers", "One supplier by tender, 3 + 1 + 1", "Cleaning, security"], ["Stream of different assignments", "Panel with rate card and mini-competitions", "Consulting, IT services"], ["No real alternative in the horizon", "Sole-source negotiation", "Incumbent software"]], note: "This is the slide to remember from today. Ask each participant to say which row their project is in, and why." },
    { k: "steps", h: "Fieldwork 2, before Session 3", s: [["Finish", "The one-page strategy paper"], ["Present", "30 minutes with the business owner"], ["Involve", "Risk and Compliance where triage flagged it"], ["Check", "Group frameworks and the notice date"], ["Record", "The agreed paper in your Sourcing Case"]], note: "Session 3 designs the RFx and the evaluation model. Without an agreed route, there is nothing to design." },
    { k: "table", h: "A 30-minute strategy conversation", t: [["Minutes", "Block"], ["0–5", "The problem they recognise, in their words"], ["5–15", "The route and why it fits"], ["15–22", "Options rejected and why"], ["22–27", "Timeline from the notice date"], ["27–30", "The decision you need, and by when"]], note: "Lead with the problem the business owner already feels, such as HQ complaints or the 9% uplift, not with procurement policy." },
    { k: "poll", poll: "s2-p22", note: "Use the result to pair participants for Fieldwork 2 support: those expecting the same difficulty can rehearse together." },
    { k: "takeaways", h: "Session 2 in five lines", b: ["The tool follows the strategy; the strategy follows the power position", "Continuous site services: one supplier by tender, 3 + 1 + 1", "Streams of professional and IT work: a panel with rate card", "No real competition: a prepared negotiation, never an auction", "One page records the route, the rejected options and the decision"], note: "Read them slowly. These five lines are what we will ask back at the capstone." },
    { k: "statement", h: "Next session: HOW do we run the event?", p: "Bring your agreed strategy paper. We will design the RFx, the evaluation model and the e-negotiation in Coupa.", note: "Remind them of the pre-work for Session 3 and the date of the next class." }
  ]
};
